	private static void assertInitialFallback(Path directory, String indexes, boolean singleLeaf) throws Exception {
		Path backups = directory.resolve("backups");
		Path live = directory.resolve("live");
		LmdbStore store = new LmdbStore(live.toFile(), configuration(indexes));
		Gate publication = new Gate();
		Captured committed;
		store.init();
		try {
			long baseline = fullBackup(store, backups);
			UUID generation = store.getBackingStore().backupJournalState().generation();
			TripleStore triples = store.getBackingStore().getTripleStore();
			MainState before = mainState(triples);
			assertNull(before.hot(), "An ineligible reservation must leave no ordinary-main source record");
			assertEquals(0L, before.overflowPages());
			if (singleLeaf) {
				assertEquals(1, before.depth(), "Aborting the split child must preserve the original catalog depth");
				assertEquals(1L, before.leafPages(),
						"Aborting the split child must preserve the original catalog leaf");
			} else {
				assertTrue(before.depth() > 1 && before.leafPages() > 1,
						"All 24 real index pairs must make this catalog ineligible for one-leaf source storage");
			}
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			assertEquals(baseline, publisher.acknowledgedTransactionId());
			publisher.setBeforePublication(publication::pause);
			committed = commit(store, statement("initial-fallback"), baseline + 1);
			publication.awaitSelected();
			assertNull(mainState(triples).hot(), "An ordinary commit must not retry a rejected reservation");
			assertBucketStage(triples, committed);
			assertNativeStage(triples, committed);
			assertEquals(baseline, publisher.acknowledgedTransactionId(), "The measured stage must remain unpublished");
			publication.release();
			assertPublished(store, backups, baseline, generation, List.of(committed), directory.resolve("exported"));
		} finally {
			publication.release();
			store.shutDown();
		}
		LmdbStore reopened = new LmdbStore(live.toFile(), configuration(indexes));
		reopened.init();
		try {
			TripleStore triples = reopened.getBackingStore().getTripleStore();
			assertNull(mainState(triples).hot());
			assertEquals(committed.stage().transaction, triples.getRequiredBackupTxnId());
			assertEquals(committed.stage().id, triples.getBackupOutboxHead());
			assertNativeStage(triples, committed);
			try (var connection = reopened.getConnection()) {
				assertEquals(1L, connection.size());
				Statement statement = committed.statement();
				assertTrue(
						connection.hasStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								false));
			}
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void realIndexCreationEvacuatesCatalogFramesBeforeSmallBucketFallback(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		long baseline;
		UUID generation;
		Captured seed;
		LmdbStore initial = new LmdbStore(live.toFile(), configuration("spoc"));
		initial.init();
		try {
			baseline = fullBackup(initial, backups);
			generation = initial.getBackingStore().backupJournalState().generation();
			seed = commit(initial, statement("seed"), baseline + 1);
			assertPublished(initial, backups, baseline, generation, List.of(seed), directory.resolve("seed-export"));
			assertPackContains(LmdbBackupCatalogTestSupport.unpack(mainState(initial.getBackingStore()
					.getTripleStore()).hot()), seed);
		} finally {
			initial.shutDown();
		}

		// Reconfiguration is requested through the supported reopen path. Defer only the normal maintenance gate,
		// so a real public source stage can be committed before the first index-build transaction creates its DBIs.
		DeferredStore store = new DeferredStore(live.toFile());
		Gate publication = new Gate();
		List<Captured> completed;
		store.init();
		try {
			TripleStore triples = store.getBackingStore().getTripleStore();
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			assertEquals(generation, store.getBackingStore().backupJournalState().generation());
			assertEquals(seed.stage().transaction, publisher.acknowledgedTransactionId());
			assertEquals("PENDING", triples.indexRebuildStatus());
			publisher.setBeforePublication(publication::pause);
			Captured beforeGrowth = commit(store, statement("before-growth"), baseline + 2);
			publication.awaitSelected();
			MainState eligible = mainState(triples);
			assertEquals(1, eligible.depth());
			assertEquals(1L, eligible.leafPages());
			assertEquals(0L, eligible.overflowPages());
			byte[] retainedPack = LmdbBackupCatalogTestSupport.unpack(eligible.hot());
			assertPackContains(retainedPack, beforeGrowth);

			triples.startBackgroundIndexRebuild();
			store.indexesCreated.awaitSelected();
			assertEquals("RESET", store.firstBatchPhase.get(), "The gate must follow real target-index creation");
			MainState grown = mainState(triples);
			assertTrue(grown.depth() > 1 && grown.leafPages() > 1,
					"Creating all real index pairs must grow the live main catalog");
			assertArrayEquals(eligible.hot(), grown.hot(),
					"Index maintenance must retain the actual source frames until the next source commit");
			assertEquals(seed.stage().transaction, publisher.acknowledgedTransactionId());

			Captured fallback = commit(store, statement("after-growth"), baseline + 3);
			assertNull(mainState(triples).hot(), "The ineligible source reservation must be removed atomically");
			assertArrayEquals(retainedPack,
					triples.getTxnManager()
							.doWithFreshPriority((stack, transaction) -> LmdbBackupOutboxPackTest.coldPack(stack,
									transaction, beforeGrowth.stage().transaction)),
					"Fallback must preserve the complete nonempty prior catalog pack in cold storage");
			assertBucketStage(triples, fallback);
			assertNativeStage(triples, seed);
			assertNativeStage(triples, beforeGrowth);
			assertNativeStage(triples, fallback);
			assertEquals(seed.stage().transaction, publisher.acknowledgedTransactionId(),
					"No newer publication proof may reclaim the measured source prefix");

			store.indexesCreated.release();
			assertTrue(triples.awaitIndexRebuild(30, TimeUnit.SECONDS), triples.indexRebuildStatus());
			assertEquals(24, triples.explicitIndexEntryCounts().size());
			for (long count : triples.explicitIndexEntryCounts().values()) {
				assertEquals(3L, count, "Every rebuilt index must contain the three actual public mutations");
			}
			publication.release();
			completed = List.of(seed, beforeGrowth, fallback);
			assertPublished(store, backups, baseline, generation, completed,
					directory.resolve("grown-export"));
		} finally {
			store.indexesCreated.release();
			publication.release();
			store.shutDown();
		}
		LmdbStore reopened = new LmdbStore(live.toFile(), configuration(ALL_INDEXES));
		reopened.init();
		try {
			TripleStore triples = reopened.getBackingStore().getTripleStore();
			Captured head = completed.getLast();
			assertNull(mainState(triples).hot());
			assertEquals(head.stage().transaction, triples.getRequiredBackupTxnId());
			assertEquals(head.stage().id, triples.getBackupOutboxHead());
			assertNativeStage(triples, head);
			assertEquals(24, triples.explicitIndexEntryCounts().size());
			assertPublished(reopened, backups, baseline, generation, completed,
					directory.resolve("grown-reopened-export"));
		} finally {
			reopened.shutDown();
		}
	}

	private static LmdbStoreConfig configuration(String indexes) {
		return new LmdbStoreConfig(indexes).setBackupJournalEnabled(true)
				.setForceSync(true)
				.setBulkOperationSize(0)
				.setInitialRunImportEnabled(false);
	}

	private static long fullBackup(LmdbStore store, Path backups) {
		return store.getBackupService()
				.createBackup(BackupRequest.builder(backups, BackupType.FULL).build())
				.getEndTransactionId();
	}

	private static Statement statement(String name) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:s:" + name), values.createIRI("urn:p"),
				values.createLiteral("v"));
	}

	private static Captured commit(LmdbStore store, Statement statement, long transaction) throws IOException {
		TripleStore triples = store.getBackingStore().getTripleStore();
		UUID predecessor = triples.getBackupOutboxHead();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			connection.commit();
		}
		byte[] actual;
		try (var input = triples.openBackupStage(transaction)) {
			actual = input.readAllBytes();
		}
		Stage stage;
		try (var input = new DataInputStream(new ByteArrayInputStream(actual))) {
			stage = PostCommitBackupPublisher.readStage(input, null);
		}
		assertEquals(transaction, stage.transaction);
		assertEquals(transaction - 1, stage.previousTransaction);
		assertEquals(predecessor, stage.predecessor);
		assertEquals(1, stage.count);
		assertEquals(transaction, triples.getRequiredBackupTxnId());
		assertEquals(stage.id, triples.getBackupOutboxHead());
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		try (var output = new DataOutputStream(expected)) {
			PostCommitBackupPublisher.writeStageHeader(output, stage);
			LmdbBackupDeltaCodec.writeRecords(output, List.of(new Record(true, true, statement)));
		}
		assertArrayEquals(expected.toByteArray(), actual);
		return new Captured(stage, statement, actual);
	}

	private static MainState mainState(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBStat statistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, database.get(0), statistics));
			return new MainState(statistics.ms_depth(), statistics.ms_leaf_pages(), statistics.ms_overflow_pages(),
					LmdbBackupCatalogTestSupport.read(stack, transaction));
		});
	}

	private static byte[] nativeValue(TripleStore triples, String databaseName, byte[] keyBytes) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, databaseName, 0, database));
			MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes(keyBytes));
			MDBVal value = MDBVal.malloc(stack);
			int result = mdb_get(transaction, database.get(0), key, value);
			if (result == MDB_NOTFOUND) {
				return null;
			}
			E(result);
			ByteBuffer bytes = Objects.requireNonNull(value.mv_data()).duplicate();
			byte[] owned = new byte[bytes.remaining()];
			bytes.get(owned);
			return owned;
		});
	}

	private static byte[] frame(Captured captured) {
		var encoder = new LmdbBackupChunkCodec.Encoder();
		int length = encoder.encode(captured.bytes(), captured.bytes().length);
		assertTrue(length <= 256, "The real fixture must exercise fallback for a small eligible frame");
		return Arrays.copyOf(encoder.bytes(), length);
	}

	private static void assertBucketStage(TripleStore triples, Captured captured) throws IOException {
		long transaction = captured.stage().transaction;
		String database = LmdbBackupOutbox
				.bucketDatabaseName((int) (transaction & (LmdbBackupOutbox.BUCKET_COUNT - 1)));
		byte[] key = ByteBuffer.allocate(2 * Long.BYTES).putLong(transaction).putLong(0).array();
		assertArrayEquals(frame(captured), nativeValue(triples, database, key),
				"The exact small source frame must use its real transaction's striped fallback bucket");
	}

	private static void assertNativeStage(TripleStore triples, Captured captured) throws IOException {
		try (var input = triples.openBackupStage(captured.stage().transaction)) {
			assertArrayEquals(captured.bytes(), input.readAllBytes());
		}
	}

	private static void assertPackContains(byte[] encoded, Captured captured) {
		ByteBuffer pack = ByteBuffer.wrap(encoded).order(ByteOrder.BIG_ENDIAN);
		assertEquals(PACK_MAGIC, pack.getInt());
		int count = pack.getInt();
		assertTrue(count > 0 && count <= 128, "The measured pack must contain real committed source frames");
		long previous = 0;
		boolean found = false;
		for (int index = 0; index < count; index++) {
			long transaction = pack.getLong();
			assertTrue(transaction > previous);
			previous = transaction;
			int length = pack.getInt();
			assertTrue(length > 13 && length <= 256 && length <= pack.remaining() - Integer.BYTES);
			byte[] bytes = new byte[length];
			pack.get(bytes);
			if (transaction == captured.stage().transaction) {
				assertArrayEquals(frame(captured), bytes);
				found = true;
			}
		}
		assertEquals(Integer.BYTES, pack.remaining());
		CRC32C checksum = new CRC32C();
		checksum.update(encoded, 0, encoded.length - Integer.BYTES);
		assertEquals((int) checksum.getValue(), pack.getInt());
		assertTrue(found, "The measured pack must contain the exact public statement's source frame");
	}

	private static void assertPublished(LmdbStore store, Path backups, long baseline, UUID generation,
			List<Captured> expected, Path destination) throws IOException {
		Captured last = expected.getLast();
		assertEquals(last.stage().transaction, store.getBackupService()
				.createBackup(
						BackupRequest.builder(backups, BackupType.INCREMENTAL).sinceTransactionId(baseline).build())
				.getEndTransactionId());
		PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
		assertEquals(last.stage().transaction, publisher.acknowledgedTransactionId());
		assertEquals(last.stage().id, publisher.acknowledgement().identity());
		List<Path> logs = ((LmdbBackupServiceImpl) store.getBackupService()).exportTransactionLogs(backups, baseline,
				last.stage().transaction, destination);
		assertEquals(expected.size(), logs.size());
		for (int index = 0; index < expected.size(); index++) {
			Captured captured = expected.get(index);
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			LmdbBackupDeltaCodec.write(bytes, List.of(new Record(true, true, captured.statement())),
					captured.stage().previousTransaction, generation);
			try (var input = new GZIPInputStream(Files.newInputStream(logs.get(index)))) {
				assertArrayEquals(bytes.toByteArray(), input.readAllBytes());
			}
		}
		try (var connection = store.getConnection()) {
			assertEquals(expected.size(), connection.size());
			for (Captured captured : expected) {
				Statement statement = captured.statement();
				assertTrue(
						connection.hasStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								false));
			}
		}
	}

	private record MainState(int depth, long leafPages, long overflowPages, byte[] hot) {
	}

	private record Captured(Stage stage, Statement statement, byte[] bytes) {
	}

	private static final class Gate {
		private final CountDownLatch selected = new CountDownLatch(1);
		private final CountDownLatch released = new CountDownLatch(1);

		private void pause() {
			selected.countDown();
			await(released, "The test must release its paused work");
		}

		private void awaitSelected() {
			await(selected, "The real source or index transaction must reach the test gate");
		}

		private void release() {
			released.countDown();
		}

		private static void await(CountDownLatch latch, String message) {
			try {
				assertTrue(latch.await(30, TimeUnit.SECONDS), message);
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new AssertionError(interrupted);
			}
		}
	}

	private static final class DeferredStore extends LmdbStore {
		private final Gate indexesCreated = new Gate();
		private final AtomicBoolean firstBatch = new AtomicBoolean(true);
		private final AtomicReference<String> firstBatchPhase = new AtomicReference<>();

		private DeferredStore(File directory) {
			super(directory, configuration(ALL_INDEXES));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketches, (LmdbSailStore.ValueStoreFactory) null,
					(tripleDirectory, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDirectory,
							tripleProperties, tripleConfig, values) {
						@Override
						protected void afterIndexRebuildBatch() {
							if (firstBatch.compareAndSet(true, false)) {
								firstBatchPhase.set(indexRebuildStatus());
								indexesCreated.pause();
							}
						}
					}) {
				@Override
				void startBackgroundMaintenanceAfterInitialization() {
					// The test explicitly opens the supported rebuild gate after committing its real source frame.
				}
			};
		}
	}
